/**
 * Demo catalogue for the Kiln theme: the fictional studio "Tilde Goods" — two regions (United States / USD,
 * Indonesia / IDR), one sales channel + publishable key, a warehouse with flat-rate shipping, six categories and
 * thirteen products with a price in each currency. Idempotent: it stops when the store already has a region.
 *
 *   cp seed/seed-kiln.ts <backend>/src/scripts/ && cp -r seed/images <backend>/static/demo
 *   cd <backend> && npx medusa exec ./src/scripts/seed-kiln.ts
 *
 * Images: seed/images (generated by seed/demo-images.mjs, CC0). DEMO_IMAGE_BASE sets where they are served from
 * (default: the backend's own /static/demo).
 */
import {
  createApiKeysWorkflow,
  createInventoryLevelsWorkflow,
  createCollectionsWorkflow,
  createProductCategoriesWorkflow,
  createProductsWorkflow,
  createRegionsWorkflow,
  createSalesChannelsWorkflow,
  createShippingOptionsWorkflow,
  createShippingProfilesWorkflow,
  createStockLocationsWorkflow,
  createTaxRegionsWorkflow,
  linkSalesChannelsToApiKeyWorkflow,
  linkSalesChannelsToStockLocationWorkflow,
  updateStoresWorkflow,
} from "@medusajs/medusa/core-flows"
import { ContainerRegistrationKeys, Modules, ProductStatus } from "@medusajs/framework/utils"
import type { ExecArgs } from "@medusajs/framework/types"

const BRAND = "Tilde Goods"

const CATEGORIES = [
  { name: "Tableware", handle: "tableware", image: "cat-tableware" },
  { name: "Kitchen", handle: "kitchen", image: "cat-kitchen" },
  { name: "Decor", handle: "decor", image: "cat-decor" },
  { name: "Textiles", handle: "textiles", image: "cat-textiles" },
  { name: "Lighting", handle: "lighting", image: "cat-lighting" },
  { name: "Storage", handle: "storage", image: "cat-storage" },
]

type Demo = { handle: string; title: string; category: string; maker: string; material: string; usd: number; idr: number; weight: number; options?: { title: string; values: string[]; usdStep?: number }; description: string; materials: string; care: string }
const MAKERS = [
  {
    handle: "studio-lio",
    title: "Studio Lio",
    location: "Yogyakarta, Indonesia",
    description: "A two-person pottery studio. Everything is thrown by hand and fired in a small gas kiln.",
    story: "Lio and Sari started the studio in 2016 in a rented garage, with one wheel and a kiln they built themselves. Ten years on there are two wheels, a bigger kiln and still just the two of them.\n\nThe clay comes from a quarry two hours away and every glaze is mixed in the studio. Plates and bowls are thrown in batches of thirty, dried for a week and fired twice, so the rims take daily use without chipping.",
  },
  {
    handle: "tjipto-workshop",
    title: "Tjipto Workshop",
    location: "Jepara, Indonesia",
    description: "Third-generation woodworkers. Solid timber only, finished with oil, never lacquer.",
    story: "The workshop was opened by Tjipto's grandfather in 1961 and still stands on the same street, which has been the carpenters' street of Jepara for longer than anyone remembers.\n\nThey work in solid oak, walnut and cedar, joined without screws where the piece allows it. Every board is finished with food-safe oil only, so it can be sanded and refreshed for years instead of thrown away.",
  },
  {
    handle: "north-field",
    title: "North Field",
    location: "Bandung, Indonesia",
    description: "Textiles and candles made in small runs, with natural fibres and soy wax.",
    story: "North Field is a weaving studio in the hills above Bandung, where the mornings are cool enough for wool. Four looms, six people, and a candle bench by the window.\n\nLinen is bought as yarn and woven, washed and cut in the studio; the throws are lambswool from a small spinner. Candles are poured in batches of forty, in glasses that go in the dishwasher afterwards.",
  },
  {
    handle: "rumah-anyam",
    title: "Rumah Anyam",
    location: "Lombok, Indonesia",
    description: "A weaving collective: seagrass and rattan baskets woven the traditional way.",
    story: "Rumah Anyam is a collective of twenty-two weavers in three villages on Lombok. Each basket is woven by one person from start to finish and carries her initials on the base.\n\nThe seagrass is harvested after the rains, dried in the sun for two weeks and woven without dye. Baskets are shipped folded flat and spring back into shape in a day.",
  },
]

const PRODUCTS: Demo[] = [
  { handle: "stoneware-dinner-plate", maker: "studio-lio", material: "Stoneware", title: "Stoneware Dinner Plate", category: "tableware", usd: 28, idr: 420000, weight: 700, options: { title: "Size", values: ["22 cm", "27 cm"], usdStep: 6 }, materials: "Glazed stoneware", care: "Dishwasher and oven safe", description: "A plate with a soft matte glaze and a slightly raised rim. Fired twice, so the edge takes daily use without chipping." },
  { handle: "ceramic-serving-bowl", maker: "studio-lio", material: "Stoneware", title: "Ceramic Serving Bowl", category: "tableware", usd: 46, idr: 690000, weight: 1100, materials: "Glazed stoneware", care: "Dishwasher safe", description: "A wide, low bowl for salads and sharing plates. Each one is thrown by hand, so the rim varies a little." },
  { handle: "ribbed-stoneware-mug", maker: "studio-lio", material: "Stoneware", title: "Ribbed Stoneware Mug", category: "tableware", usd: 22, idr: 330000, weight: 350, options: { title: "Colour", values: ["Ash", "Bone"] }, materials: "Stoneware", care: "Dishwasher safe", description: "A 350 ml mug with fine ribs on the outside that keep it easy to hold when the coffee is hot." },
  { handle: "oak-serving-board", maker: "tjipto-workshop", material: "Oak", title: "Oak Serving Board", category: "kitchen", usd: 54, idr: 810000, weight: 900, options: { title: "Size", values: ["Small", "Large"], usdStep: 18 }, materials: "Solid European oak, food-safe oil", care: "Hand wash, re-oil monthly", description: "A thick oak board with a hanging hole. Finished with food-safe oil only, so it can be sanded and refreshed for years." },
  { handle: "walnut-catch-all-tray", maker: "tjipto-workshop", material: "Walnut", title: "Walnut Catch-all Tray", category: "kitchen", usd: 38, idr: 570000, weight: 500, materials: "Solid walnut", care: "Wipe with a damp cloth", description: "A shallow tray for keys, spoons or jewellery. The raised edge is cut from the same board, so the grain runs straight through." },
  { handle: "tapered-bud-vase", maker: "studio-lio", material: "Stoneware", title: "Tapered Bud Vase", category: "decor", usd: 32, idr: 480000, weight: 400, materials: "Stoneware", care: "Hand wash", description: "A narrow-necked vase for one or two stems. Weighted at the base so a tall branch will not tip it." },
  { handle: "soy-candle", maker: "north-field", material: "Soy wax", title: "Soy Candle", category: "decor", usd: 24, idr: 360000, weight: 450, options: { title: "Scent", values: ["Cedar", "Fig", "Unscented"] }, materials: "Soy wax, cotton wick, glass", care: "Trim the wick to 5 mm before lighting", description: "A 50-hour candle in a reusable glass. Soy wax burns cool and clean; the glass goes in the dishwasher afterwards." },
  { handle: "linen-napkin-set", maker: "north-field", material: "Linen", title: "Linen Napkin Set", category: "textiles", usd: 36, idr: 540000, weight: 200, options: { title: "Colour", values: ["Natural", "Charcoal"] }, materials: "100% washed linen", care: "Machine wash warm, tumble low", description: "Four 45 cm napkins in stonewashed linen. They soften with every wash and look best a little creased." },
  { handle: "wool-throw", maker: "north-field", material: "Wool", title: "Wool Throw", category: "textiles", usd: 120, idr: 1800000, weight: 1300, materials: "100% lambswool", care: "Dry clean or hand wash cold", description: "A 130 × 180 cm throw woven from lambswool, with a twisted fringe. Warm without being heavy." },
  { handle: "paper-cone-lamp", maker: "tjipto-workshop", material: "Paper", title: "Paper Cone Lamp", category: "lighting", usd: 88, idr: 1320000, weight: 1600, materials: "Washi paper shade, oak base", care: "Dust with a soft brush", description: "A table lamp with a hand-folded paper shade on a turned oak base. Takes a standard E27 bulb; fitted with a fabric cord." },
  { handle: "wall-hook-rail", maker: "tjipto-workshop", material: "Oak", title: "Wall Hook Rail", category: "storage", usd: 42, idr: 630000, weight: 700, materials: "Solid oak, brass hooks", care: "Wipe clean", description: "A 45 cm oak rail with three brass hooks. Comes with screws and wall plugs; the holes are pre-drilled and countersunk." },
  { handle: "seagrass-basket", maker: "rumah-anyam", material: "Seagrass", title: "Seagrass Basket", category: "storage", usd: 34, idr: 510000, weight: 600, options: { title: "Size", values: ["Small", "Medium", "Large"], usdStep: 10 }, materials: "Hand-woven seagrass", care: "Keep dry", description: "A sturdy woven basket with two handles. Holds its shape when empty and folds flat for shipping." },
  { handle: "cedar-storage-box", maker: "tjipto-workshop", material: "Cedar", title: "Cedar Storage Box", category: "storage", usd: 64, idr: 960000, weight: 1500, materials: "Solid cedar", care: "Sand lightly to refresh the scent", description: "A lidded box in aromatic cedar for sweaters and linens. The scent keeps moths away without anything sprayed on." },
]

export default async function seed({ container }: ExecArgs) {
  const logger = container.resolve(ContainerRegistrationKeys.LOGGER)
  const query = container.resolve(ContainerRegistrationKeys.QUERY)
  const link = container.resolve(ContainerRegistrationKeys.LINK)
  const fulfillmentService = container.resolve(Modules.FULFILLMENT)
  const storeService = container.resolve(Modules.STORE)
  const base = process.env.DEMO_IMAGE_BASE || `${process.env.MEDUSA_BACKEND_URL || `http://127.0.0.1:${process.env.PORT || 9000}`}/static/demo`
  const img = (name: string) => `${base}/${name}.jpg`

  const { data: existing } = await query.graph({ entity: "region", fields: ["id"] })
  if (existing.length) {
    logger.info("seed-kiln: the store already has a region, nothing to do")
    return
  }

  const [store] = await storeService.listStores()
  const { result: [channel] } = await createSalesChannelsWorkflow(container).run({ input: { salesChannelsData: [{ name: "Online store" }] } })
  await updateStoresWorkflow(container).run({
    input: {
      selector: { id: store.id },
      update: {
        name: BRAND,
        supported_currencies: [{ currency_code: "usd", is_default: true }, { currency_code: "idr" }],
        default_sales_channel_id: channel.id,
      },
    },
  })

  const { result: regions } = await createRegionsWorkflow(container).run({
    input: {
      regions: [
        { name: "United States", currency_code: "usd", countries: ["us"], payment_providers: ["pp_system_default"] },
        { name: "Indonesia", currency_code: "idr", countries: ["id"], payment_providers: ["pp_system_default"] },
      ],
    },
  })
  await createTaxRegionsWorkflow(container).run({ input: [{ country_code: "us", provider_id: "tp_system" }, { country_code: "id", provider_id: "tp_system" }] })

  const { result: [location] } = await createStockLocationsWorkflow(container).run({
    input: { locations: [{ name: `${BRAND} studio`, address: { city: "Jepara", country_code: "ID", address_1: "Jl. Studio 1" } }] },
  })
  await link.create({ [Modules.STOCK_LOCATION]: { stock_location_id: location.id }, [Modules.FULFILLMENT]: { fulfillment_provider_id: "manual_manual" } })
  await linkSalesChannelsToStockLocationWorkflow(container).run({ input: { id: location.id, add: [channel.id] } })

  const { result: [profile] } = await createShippingProfilesWorkflow(container).run({ input: { data: [{ name: "Default", type: "default" }] } })
  const set = await fulfillmentService.createFulfillmentSets({
    name: `${BRAND} delivery`,
    type: "shipping",
    service_zones: [
      { name: "United States", geo_zones: [{ country_code: "us", type: "country" }] },
      { name: "Indonesia", geo_zones: [{ country_code: "id", type: "country" }] },
    ],
  })
  await link.create({ [Modules.STOCK_LOCATION]: { stock_location_id: location.id }, [Modules.FULFILLMENT]: { fulfillment_set_id: set.id } })
  const zone = (name: string) => set.service_zones.find((z) => z.name === name)!.id
  const rules = [
    { attribute: "enabled_in_store", value: "true", operator: "eq" as const },
    { attribute: "is_return", value: "false", operator: "eq" as const },
  ]
  await createShippingOptionsWorkflow(container).run({
    input: [
      { name: "Standard", price_type: "flat", provider_id: "manual_manual", service_zone_id: zone("United States"), shipping_profile_id: profile.id, type: { label: "Standard", description: "5–8 business days", code: "standard" }, prices: [{ currency_code: "usd", amount: 9 }], rules },
      { name: "Express", price_type: "flat", provider_id: "manual_manual", service_zone_id: zone("United States"), shipping_profile_id: profile.id, type: { label: "Express", description: "2–3 business days", code: "express" }, prices: [{ currency_code: "usd", amount: 24 }], rules },
      { name: "Reguler", price_type: "flat", provider_id: "manual_manual", service_zone_id: zone("Indonesia"), shipping_profile_id: profile.id, type: { label: "Reguler", description: "3–6 hari kerja", code: "standard" }, prices: [{ currency_code: "idr", amount: 25000 }], rules },
      // Free above $100 (price rule on item_total): drives the storefront's free-shipping nudge
      { name: "Free shipping", price_type: "flat", provider_id: "manual_manual", service_zone_id: zone("United States"), shipping_profile_id: profile.id, type: { label: "Free shipping", description: "Orders over $100, 5–8 business days", code: "free" }, prices: [{ currency_code: "usd", amount: 0, rules: [{ attribute: "item_total", operator: "gte" as const, value: 100 }] }], rules },
    ],
  })

  const { result: [key] } = await createApiKeysWorkflow(container).run({ input: { api_keys: [{ title: "Storefront", type: "publishable", created_by: "" }] } })
  await linkSalesChannelsToApiKeyWorkflow(container).run({ input: { id: key.id, add: [channel.id] } })

  const { result: categories } = await createProductCategoriesWorkflow(container).run({
    input: { product_categories: CATEGORIES.map((c) => ({ name: c.name, handle: c.handle, is_active: true, metadata: { image: img(c.image) } })) },
  })
  const categoryId = (handle: string) => categories.find((c) => c.handle === handle)!.id

  // Makers: one collection each (the storefront's "Maker" filter and /makers pages read collections + metadata)
  const { result: collections } = await createCollectionsWorkflow(container).run({
    input: { collections: MAKERS.map((m) => ({ title: m.title, handle: m.handle, metadata: { location: m.location, description: m.description, story: m.story } })) },
  })
  const collectionId = (handle: string) => collections.find((c) => c.handle === handle)!.id

  await createProductsWorkflow(container).run({
    input: {
      products: PRODUCTS.map((p) => {
        const values = p.options?.values ?? ["Default"]
        return {
          title: p.title,
          handle: p.handle,
          description: p.description,
          status: ProductStatus.PUBLISHED,
          category_ids: [categoryId(p.category)],
          collection_id: collectionId(p.maker),
          thumbnail: img(p.handle),
          images: [{ url: img(p.handle) }],
          weight: p.weight,
          shipping_profile_id: profile.id,
          sales_channels: [{ id: channel.id }],
          metadata: { material: p.material, materials: p.materials, care: p.care },
          options: [{ title: p.options?.title ?? "Default", values }],
          variants: values.map((v, i) => ({
            title: v,
            sku: `${p.handle}-${v.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
            options: { [p.options?.title ?? "Default"]: v },
            manage_inventory: true,
            prices: [
              { currency_code: "usd", amount: p.usd + i * (p.options?.usdStep ?? 0) },
              { currency_code: "idr", amount: p.idr + i * (p.options?.usdStep ?? 0) * 15000 },
            ],
          })),
        }
      }),
    },
  })

  const { data: items } = await query.graph({ entity: "inventory_item", fields: ["id"] })
  await createInventoryLevelsWorkflow(container).run({
    input: { inventory_levels: items.map((i) => ({ inventory_item_id: i.id, location_id: location.id, stocked_quantity: 25 })) },
  })

  logger.info(`seed-kiln: ${regions.length} regions, ${categories.length} categories, ${PRODUCTS.length} products`)
  logger.info(`seed-kiln: publishable key ${key.token}`)
}
